function init(){setupTabs(),setupThemeToggle(),setupBookmark(),setupGalleryLightbox(),setupJourneyIntegration()}function setupTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>{e.classList.remove("active"),e.setAttribute("hidden","")}),n.classList.add("active"),n.setAttribute("aria-selected","true");const o=document.getElementById(n.dataset.tab);o.classList.add("active"),o.removeAttribute("hidden")})})}function setupThemeToggle(){const e=document.getElementById("theme-toggle");e.addEventListener("click",()=>{document.body.classList.toggle("light-theme"),localStorage.setItem("theme",document.body.classList.contains("light-theme")?"light":"dark"),e.textContent=document.body.classList.contains("light-theme")?"☀️":"🌙"}),"light"===localStorage.getItem("theme")&&(document.body.classList.add("light-theme"),e.textContent="☀️")}function setupBookmark(){const e=document.getElementById("bookmark-btn"),t="art-madhubani",n=()=>{e.textContent=window.Journey&&window.Journey.isSaved(t)?"✅ Saved to Journey":"🔖 Bookmark to My Journey"};n(),e.addEventListener("click",()=>{window.Journey&&(window.Journey.toggle({id:t,explorerPage:"frontend/madhubani-painting-explorer/index.html",title:"Madhubani Painting",thumbnail:"https://placehold.co/100/e11d48/fff",category:"art"}),n())})}function setupGalleryLightbox(){document.querySelectorAll(".gallery-item img").forEach(e=>{e.addEventListener("click",()=>{alert(`Lightbox view: ${e.alt}\n(In a production app, this would open a full-screen modal overlay)`)})})}function setupJourneyIntegration(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("frontend/madhubani-painting-explorer/index.html",[{id:"art-madhubani",title:"Madhubani Painting",description:"Folk art from Bihar known for geometric patterns.",link:"#"}])}document.addEventListener("DOMContentLoaded",init);